'use strict';
document.body.insertAdjacentHTML('beforeend',`<dialog id="real3dDialog" class="real-3d-dialog" aria-labelledby="real3dTitle"><div class="real3d-top"><div><span class="eyebrow">TOCÁ, GIRÁ Y DESCUBRÍ</span><h2 id="real3dTitle">Las montañas de tu misión.</h2></div><button id="closeReal3d" aria-label="Cerrar relieve 3D">✕</button></div><div class="real3d-toolbar"><button id="viewRealLocal" class="primary">Site01 · relieve real</button><button id="viewRealMoon">Luna completa · contexto</button><label>Colores<select id="real3dLayer"><option value="slope">Pendiente · candidatos en verde</option><option value="height">Altura del terreno</option></select></label><label>Exageración vertical <b id="realExLabel">2×</b><input id="realEx" type="range" min="1" max="8" step="0.5" value="2"></label><button id="resetRealCamera">Restablecer vista</button></div><div class="real3d-stage"><canvas id="real3dCanvas" aria-label="Relieve lunar 3D interactivo; arrastrar para rotar, rueda para acercar"></canvas><div id="real3dStatus" role="status">Preparando la vista…</div></div><div class="real3d-cat"><img src="assets/felicette-terrain.png" alt="Félicette con su mapa"><p id="real3dCatTip">¡Mirá las montañas! El verde cumple tu límite de pendiente. Tocá un punto para conocerlo; todavía hay que revisar rocas y otros riesgos.</p></div><div class="real3d-bottom"><div><b>Arrastrá para girar · rueda o pellizco para acercar</b><p id="real3dHelp">Tocá un punto y después elegí «Usar este lugar».</p><div class="real3d-legend"><span>🟢 ≤10° · candidato por pendiente</span><span>🟡 10–15° · mayor inclinación</span><span>🔴 >15° · no cumple ese criterio</span></div><small>Las categorías se basan en la mayor pendiente nativa dentro de una celda de 20 m. No certifican seguridad: faltan rocas, rugosidad e incertidumbre local. Las luces de esta vista son ilustrativas, no una simulación de sombras.</small></div><div><label>Límite para verde (°)<input id="realSlopeLimit" type="number" min="1" max="15" value="10"></label><button id="useRealPoint" class="primary" disabled>Usar este lugar →</button><p id="realPointDetails"></p></div></div></dialog>`);
let realRenderer,realScene,realCamera,realOrbit,realMesh,realMoon,realMarker,realArrows,realView='local',realChosen=null,realDragStart=null,realFrame=null;
function heightColor(z){const t=Math.max(0,Math.min(1,(z+600)/2700));return new THREE.Color().setHSL((1-t)*.65,.7,.48);}
function slopeColor(v){const lim=+$('realSlopeLimit').value;return !Number.isFinite(v)?[110,122,137]:v<=lim?[85,207,140]:v<=Math.max(15,lim+3)?[244,191,77]:[222,80,90];}
function colorTexture(){const t=RM.terrain,N=t.meta.width,data=new Uint8Array(N*N*4),mode=$('real3dLayer').value;for(let k=0;k<N*N;k++){const rgb=mode==='slope'?slopeColor(t.slope[k]):heightColor(t.mean[k]).toArray().map(v=>Math.round(v*255));data.set([...rgb,255],k*4);}const tex=new THREE.DataTexture(data,N,N,THREE.RGBAFormat);tex.magFilter=tex.minFilter=THREE.NearestFilter;tex.needsUpdate=true;return tex;}
function updateRealSurface(){if(!realMesh)return;const t=RM.terrain,ex=+$('realEx').value,p=realMesh.geometry.attributes.position,n=201;for(let j=0;j<n;j++)for(let i=0;i<n;i++){const ii=Math.min(799,i*4),jj=Math.min(799,j*4);p.setY(j*n+i,t.mean[jj*800+ii]/1000*ex);}p.needsUpdate=true;realMesh.geometry.computeVertexNormals();realMesh.material.map?.dispose();realMesh.material.map=colorTexture();realMesh.material.needsUpdate=true;$('realExLabel').textContent=ex+'×';if(realMarker&&realChosen)realMarker.position.y=realChosen.elevation/1000*ex+.07;updateRealArrows();updateRealMoon();}
function createRealSurface(){const n=201,ps=[],uv=[],idx=[];for(let j=0;j<n;j++)for(let i=0;i<n;i++){ps.push(-8+i/200*16,0,-8+j/200*16);uv.push(i/200,j/200);}for(let j=0;j<n-1;j++)for(let i=0;i<n-1;i++){const a=j*n+i,b=a+1,c=a+n;idx.push(a,c,b,b,c,c+1);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(ps,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);realMesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({roughness:1,metalness:0,side:THREE.DoubleSide}));realScene.add(realMesh);const grid=new THREE.GridHelper(16,8,0x537882,0x2e465c);grid.position.y=-.7;realScene.add(grid);realMesh.userData.grid=grid;realMarker=new THREE.Mesh(new THREE.SphereGeometry(.10,16,12),new THREE.MeshBasicMaterial({color:0xeaffc2}));realScene.add(realMarker);realMarker.visible=false;realArrows=new THREE.Group();realScene.add(realArrows);updateRealSurface();}
function updateRealMoon(){if(!realMoon||!globalDem)return;const p=realMoon.geometry.attributes.position,col=realMoon.geometry.attributes.color,ex=+$('realEx').value;let k=0;for(let j=0;j<=90;j++)for(let i=0;i<=180;i++){const lat=90-j*2,lon=-180+i*2,di=Math.min(719,Math.max(0,Math.floor((90-lat)*4)))*1440+Math.min(1439,Math.max(0,Math.floor((lon+180)*4))),z=globalDem[di],rr=1+z/1737400*ex;p.setXYZ(k,rr*Math.cos(lat*rad)*Math.sin(lon*rad),rr*Math.sin(lat*rad),rr*Math.cos(lat*rad)*Math.cos(lon*rad));const cc=heightColor(z/5);col.setXYZ(k,cc.r,cc.g,cc.b);k++;}p.needsUpdate=true;col.needsUpdate=true;realMoon.geometry.computeVertexNormals();}
function createRealMoon(){const n=181,m=91,ps=new Float32Array(n*m*3),colors=new Float32Array(n*m*3),idx=[];for(let j=0;j<m-1;j++)for(let i=0;i<n-1;i++){const a=j*n+i,b=a+1,c=a+n;idx.push(a,b,c,b,c+1,c);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(ps,3));g.setAttribute('color',new THREE.BufferAttribute(colors,3));g.setIndex(idx);realMoon=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:1}));realMoon.visible=false;realScene.add(realMoon);const pin=new THREE.Mesh(new THREE.SphereGeometry(.015,16,10),new THREE.MeshBasicMaterial({color:0xeaffe0})),ll=C.ll(-11000,-12000);pin.position.set(1.015*Math.cos(ll.lat*rad)*Math.sin(ll.lon*rad),1.015*Math.sin(ll.lat*rad),1.015*Math.cos(ll.lat*rad)*Math.cos(ll.lon*rad));realMoon.add(pin);updateRealMoon();}
function updateRealArrows(){if(!realArrows||!RM.ready||!records.length)return;while(realArrows.children.length){const a=realArrows.children[0];realArrows.remove(a);a.dispose?.();}const pub=document.body.classList.contains('audience-public'),s=sites[pub?mission.site:+$('site').value],info=RM.terrain.inspect(s,RM.radius),a=evaluate(s,records[pub?missionIndex()+mission.previewHour:dateIndex()],pub?mission.height:number('height')),ex=+$('realEx').value,origin=new THREE.Vector3((info.x+11000)/1000,info.elevation/1000*ex+.05,-(info.y+12000)/1000);for(const [p,color]of[[a.sun,0xf7d16b],[a.earth,0x6dd2ee]]){const v=new THREE.Vector3(Math.sin(p.az*rad)*Math.cos(p.el*rad),Math.sin(p.el*rad)*ex,-Math.cos(p.az*rad)*Math.cos(p.el*rad)).normalize();realArrows.add(new THREE.ArrowHelper(v,origin,4,color,.3,.16));}}
function realCameraView(view){realView=view;const local=view==='local';realMesh.visible=local;realMesh.userData.grid.visible=local;realMoon.visible=!local;realArrows.visible=local;realMarker.visible=local&&!!realChosen;realOrbit.target.set(0,local?.7:0,0);realCamera.near=local?.01:.001;realCamera.far=1000;realCamera.position.set(local?-14:0,local?14:-2.2,local?17:2.2);realOrbit.minDistance=local?1:1.05;realOrbit.maxDistance=local?60:7;realCamera.updateProjectionMatrix();$('real3dHelp').textContent=local?'Tocá un punto del relieve y después «Usar este lugar». Las flechas son direcciones del escenario: amarillo Sol, celeste Tierra.':'Luna global con alturas LOLA de baja resolución. Los colores muestran altitud, no zonas seguras. Para decidir, volvé al detalle real de Site01.';$('real3dLayer').disabled=!local;$('useRealPoint').disabled=!local||!realChosen?.covered;refreshRealLegend();}
function initReal3D(){if(!window.THREE)throw Error('No se pudo cargar el visor 3D.');const canvas=$('real3dCanvas');realRenderer=new THREE.WebGLRenderer({canvas,antialias:true});realRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));realScene=new THREE.Scene();realScene.background=new THREE.Color(0x09172a);realCamera=new THREE.PerspectiveCamera(42,1,.01,1000);realScene.add(new THREE.HemisphereLight(0xd9f3ed,0x34506b,1));const light=new THREE.DirectionalLight(0xffffff,.7);light.position.set(-8,12,7);realScene.add(light);realOrbit=new THREE.OrbitControls(realCamera,canvas);realOrbit.enableDamping=true;realOrbit.maxPolarAngle=Math.PI*.95;createRealSurface();createRealMoon();realCameraView('local');LunaresMotion.attach($('real3dDialog'),()=>{if($('real3dDialog').open)realCamera.position.sub(realOrbit.target).applyAxisAngle(realCamera.up,.005).add(realOrbit.target);},{mount:$('real3dDialog').querySelector('.real3d-bottom')});new ResizeObserver(()=>{const b=canvas.parentElement.getBoundingClientRect();if(b.width&&b.height){realRenderer.setSize(b.width,b.height,false);realCamera.aspect=b.width/b.height;realCamera.updateProjectionMatrix();}}).observe(canvas.parentElement);
 canvas.onpointerdown=e=>realDragStart={x:e.clientX,y:e.clientY};canvas.onpointerup=e=>{if(realView!=='local'||!realDragStart||Math.hypot(e.clientX-realDragStart.x,e.clientY-realDragStart.y)>5)return;const b=canvas.getBoundingClientRect(),q=new THREE.Vector2((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1),ray=new THREE.Raycaster();ray.setFromCamera(q,realCamera);const hits=ray.intersectObject(realMesh);if(!hits.length)return;const v=hits[0].point,x=v.x*1000-11000,y=-v.z*1000-12000,s=C.ll(x,y);realChosen={...s,...RM.terrain.inspect(s,RM.radius)};realMarker.position.set(v.x,realChosen.elevation/1000*(+$('realEx').value)+.07,v.z);realMarker.visible=true;$('realPointDetails').textContent=`${s.lat.toFixed(5)}°, ${s.lon.toFixed(5)}° · ${realChosen.elevation.toFixed(0)} m · pendiente máxima de celda ${realChosen.slope.toFixed(1)}°. ${realChosen.covered?'Cobertura para el radio seleccionado.':'Horizonte incompleto cerca del borde: elegí un punto más central.'}`;$('useRealPoint').disabled=!realChosen.covered;$('real3dCatTip').textContent=realChosen.covered?(realChosen.slope<=+$('realSlopeLimit').value?`La celda tiene ${realChosen.slope.toFixed(1)}° de pendiente máxima: cumple tu límite. Podés comparar su luz y comunicación; el verde solo evalúa inclinación.`:`Esta celda llega a ${realChosen.slope.toFixed(1)}° y supera tu límite. Podés explorar sus condiciones, pero no cumple el criterio de pendiente que elegiste.`):'Estamos cerca del borde. Faltan alturas alrededor para completar el horizonte: buscá un lugar más central.';};
}
window.openReal3D=function(){if(!RM.ready)return toast('Esperá a que cargue el terreno.');$('real3dDialog').showModal();try{if(!realRenderer)initReal3D();updateRealArrows();$('real3dStatus').textContent='LOLA real · Site01 16 × 16 km · malla visual ≈80 m · capa de pendientes 20 m';const loop=()=>{if(!$('real3dDialog').open)return;realOrbit.update();realRenderer.render(realScene,realCamera);realFrame=requestAnimationFrame(loop);};loop();}catch(e){$('real3dStatus').textContent='El dispositivo no pudo abrir WebGL: '+e.message;}};
$('closeReal3d').onclick=()=>$('real3dDialog').close();$('real3dDialog').onclose=()=>cancelAnimationFrame(realFrame);$('viewRealLocal').onclick=()=>realCameraView('local');$('viewRealMoon').onclick=()=>realCameraView('moon');$('realEx').oninput=$('real3dLayer').onchange=$('realSlopeLimit').onchange=()=>{const limit=$('realSlopeLimit');if(!limit.checkValidity())return;updateRealSurface();refreshRealLegend();};$('resetRealCamera').onclick=()=>realCameraView(realView);$('useRealPoint').onclick=()=>{try{pickRealSite(realChosen.lon,realChosen.lat);$('real3dDialog').close();toast('Elegiste una ubicación del terreno real.');}catch(e){$('realPointDetails').textContent=e.message;}};

function refreshRealLegend(){const el=$('real3dDialog').querySelector('.real3d-legend'),lim=+$('realSlopeLimit').value;el.innerHTML=realView!=='local'?'<span>Altitud global: colores fríos → bajos; cálidos → altos. Marcador blanco: Site01. No es un mapa de seguridad.</span>':$('real3dLayer').value==='height'?'<span>Altura de Site01: −523 a +1.959 m respecto al radio lunar de referencia. El color no mide aptitud.</span>':`<span>🟢 ≤${lim}° · candidato por pendiente</span><span>🟡 hasta ${Math.max(15,lim+3)}° · precaución</span><span>🔴 mayor pendiente</span>`;}
